+/** Lua/C API: args (parent, field name string); result is one value from __index. */
+static int wslua_debugger_l_getfield(lua_State *L)
+{
+    lua_getfield(L, 1, luaL_checkstring(L, 2));
+    return 1;
+}
+
+/** Lua/C API: args (parent, key); result from __index / gettable. */
+static int wslua_debugger_l_getindexed(lua_State *L)
+{
+    lua_pushvalue(L, 2);
+    lua_gettable(L, 1);
+    return 1;
+}
