+/**
+ * Type string for the variables UI: Wireshark class name from userdata/table
+ * @c __typeof when set, otherwise the Lua type name.
+ */
+static char *wslua_debugger_variable_type_string(lua_State *L, int idx)
+{
+    const char *wname = wslua_typeof(L, idx);
+    if (wname && g_strcmp0(wname, wslua_typeof_unknown) != 0)
+    {
+        return g_strdup(wname);
+    }
+    return g_strdup(lua_typename(L, lua_type(L, idx)));
+}
