+static int64_t wslua_debugger_count_metatable_named_entries(lua_State *L, int mt_idx,
+                                                            const char *field)
+{
+    int64_t count = 0;
+    lua_getfield(L, mt_idx, field);
+    if (!lua_istable(L, -1))
+    {
+        lua_pop(L, 1);
+        return 0;
+    }
+    lua_pushnil(L);
+    while (lua_next(L, -2) != 0)
+    {
+        if (lua_type(L, -2) == LUA_TSTRING)
+        {
+            const char *k = lua_tostring(L, -2);
+            if (k && k[0] != '_')
+            {
+                ++count;
+            }
+        }
+        lua_pop(L, 1);
+    }
+    lua_pop(L, 1);
+    return count;
+}
