+/**
+ * Append Wireshark userdata members (attributes, instance methods, class
+ * methods) for the variables tree.
+ * @param L Lua state; @a ud_idx must point at full userdata.
+ * @param variables_array Output array (wslua_variable_t).
+ */
+static void wslua_debugger_append_userdata_members(lua_State *L, int ud_idx,
+                                                  GArray *variables_array)
+{
+    const int ud_abs = wslua_debugger_abs_index(L, ud_idx);
+    if (lua_type(L, ud_abs) != LUA_TUSERDATA || lua_islightuserdata(L, ud_abs))
+    {
+        return;
+    }
+    if (!lua_getmetatable(L, ud_abs))
+    {
+        return;
+    }
+    const int mt = lua_gettop(L);
+
+    /* --- Attributes (__getters): invoke each getter via __index --- */
+    lua_getfield(L, mt, "__getters");
+    GPtrArray *getter_names = g_ptr_array_new_with_free_func(g_free);
+    if (lua_istable(L, -1))
+    {
+        lua_pushnil(L);
+        while (lua_next(L, -2) != 0)
+        {
+            if (lua_type(L, -2) == LUA_TSTRING)
+            {
+                const char *k = lua_tostring(L, -2);
+                if (k && k[0] != '_')
+                {
+                    g_ptr_array_add(getter_names, g_strdup(k));
+                }
+            }
+            lua_pop(L, 1);
+        }
+    }
+    lua_pop(L, 1); /* __getters or nil */
+
+    for (unsigned getter_i = 0; getter_i < getter_names->len; getter_i++)
+    {
+        const char *attr_name = (const char *)g_ptr_array_index(getter_names, getter_i);
+        lua_pushcfunction(L, wslua_debugger_l_getfield);
+        lua_pushvalue(L, ud_abs);
+        lua_pushstring(L, attr_name);
+        wslua_variable_t variable;
+        variable.name = g_strdup(attr_name);
+        if (lua_pcall(L, 2, 1, 0) == LUA_OK)
+        {
+            variable.type = wslua_debugger_variable_type_string(L, -1);
+            variable.value = wslua_debugger_describe_value(L, -1);
+            variable.can_expand = wslua_debugger_value_can_expand(L, -1);
+            lua_pop(L, 1);
+        }
+        else
+        {
+            const char *err = lua_tostring(L, -1);
+            variable.type = g_strdup("error");
+            variable.value = g_strdup(err ? err : "(error)");
+            variable.can_expand = false;
+            lua_pop(L, 1);
+        }
+        g_array_append_val(variables_array, variable);
+    }
+    g_ptr_array_free(getter_names, TRUE);
+
+    /* --- Instance methods (__methods table on instance metatable) --- */
+    lua_getfield(L, mt, "__methods");
+    if (lua_istable(L, -1))
+    {
+        lua_pushnil(L);
+        while (lua_next(L, -2) != 0)
+        {
+            if (lua_type(L, -2) == LUA_TSTRING && lua_isfunction(L, -1))
+            {
+                const char *mname = lua_tostring(L, -2);
+                if (mname && mname[0] != '_')
+                {
+                    wslua_variable_t variable;
+                    variable.name = g_strdup(mname);
+                    variable.type = g_strdup("method");
+                    variable.value = g_strdup("");
+                    variable.can_expand = false;
+                    g_array_append_val(variables_array, variable);
+                }
+            }
+            lua_pop(L, 1);
+        }
+        lua_pop(L, 1);
+    }
+    else
+    {
+        lua_pop(L, 1);
+    }
+
+    lua_pop(L, 1); /* metatable */
+
+    /* --- Class (static) methods on the global class table --- */
+    const char *classname = wslua_typeof(L, ud_abs);
+    if (!classname || g_strcmp0(classname, wslua_typeof_unknown) == 0)
+    {
+        return;
+    }
+    lua_getglobal(L, classname);
+    if (!lua_istable(L, -1))
+    {
+        lua_pop(L, 1);
+        return;
+    }
+    lua_pushnil(L);
+    while (lua_next(L, -2) != 0)
+    {
+        if (lua_type(L, -2) == LUA_TSTRING && lua_isfunction(L, -1))
+        {
+            const char *mname = lua_tostring(L, -2);
+            if (mname && mname[0] != '_')
+            {
+                wslua_variable_t variable;
+                variable.name = g_strdup_printf("%s (class)", mname);
+                variable.type = g_strdup("class method");
+                variable.value = g_strdup("");
+                variable.can_expand = false;
+                g_array_append_val(variables_array, variable);
+            }
+        }
+        lua_pop(L, 1);
+    }
+    lua_pop(L, 1);
 }

